import Foundation

/// 行业本地词库：275 条行话，和技术词库合在一起参与匹配。
/// 选中某个行业时，该行业词条优先命中；选中「自动」则不偏向任何行业。
/// 数据由 Windows 版同一份词库生成，两边内容一致。
enum IndustryTerms {

    /// 行业代码与显示名，第一项是「自动（全部行业）」。
    static let builtinDomains: [(String, String)] = [
        ("auto", "自动（全部行业）"),
        ("edu", "教育培训"),
        ("ec", "电商运营"),
        ("fin", "金融财税"),
        ("law", "法律合规"),
        ("med", "医疗健康"),
        ("mfg", "制造工业"),
        ("car", "汽车"),
        ("estate", "房地产建筑"),
        ("hr", "人力资源"),
        ("jargon", "互联网职场黑话"),
        ("mkt", "市场营销"),
        ("logi", "物流供应链"),
        ("retail", "餐饮零售")
    ]

    private static var cached: [Terminology.Term]?

    static func all() -> [Terminology.Term] {
        if let c = cached { return c }
        var list: [Terminology.Term] = []
        if let data = rawJSON.data(using: .utf8),
           let arr = try? JSONSerialization.jsonObject(with: data) as? [[String: Any]] {
            list = arr.map { item in
                Terminology.Term(n: item["n"] as? String ?? "",
                                 a: item["a"] as? String ?? "",
                                 d: item["d"] as? String ?? "",
                                 x: item["x"] as? String ?? "",
                                 c: item["c"] as? String ?? "",
                                 i: item["i"] as? String ?? "")
            }
        }
        cached = list
        return list
    }

    static func label(for key: String) -> String {
        for (k, v) in domains() where k == key { return v }
        return "自动（全部行业）"
    }

    static func isKnown(_ key: String) -> Bool {
        domains().contains { $0.0 == key }
    }

    /// 内置行业 + 用户自建行业/岗位。
    static func domains() -> [(String, String)] {
        return builtinDomains + UserDict.shared.industries.map { ($0.key, $0.label) }
    }

    private static let rawJSON = ##"""
[{"n": "学分银行","a": "学银","d": "把平时学习、培训、考证攒下的学分像存钱一样存起来，按规定换成学历课程的学分。","x": "像超市积分卡，零散攒的分最后能当钱花。","c": "教育培训","i": "edu"},{"n": "学时","a": "课时","d": "一门课要求上满的小时数，报名、结课、算学费都按它计量。","x": "像驾校的练车小时数，练够才能约考。","c": "教育培训","i": "edu"},{"n": "形成性评价","a": "过程性评价","d": "平时作业、测验、出勤都算进成绩，不只靠最后一次考试定输赢。","x": "像减肥不是年底称一次重，而是每天记体重。","c": "教育培训","i": "edu"},{"n": "终结性评价","a": "","d": "只在课程结束时考一次，用这一场考试决定最终成绩。","x": "像一顿自助吃到饱，前面不吃后面猛塞。","c": "教育培训","i": "edu"},{"n": "学情画像","a": "学员画像","d": "把学员的基础、进度、薄弱点整理成一张标签清单，用来分层教学和推荐课程。","x": "像体检报告，哪项指标偏了一眼就看得出来。","c": "教育培训","i": "edu"},{"n": "续报率","a": "","d": "一期课结束后，继续报下一期的学员占比，是教培最看重的健康度指标。","x": "像健身房年卡到期，还有多少人接着续卡。","c": "教育培训","i": "edu"},{"n": "结课率","a": "完课率","d": "报名的人里真正坚持到课程结束的比例。","x": "像买了菜谱，最后真做完的菜有几道。","c": "教育培训","i": "edu"},{"n": "双师课堂","a": "双师","d": "一位老师线上主讲，一位老师线下答疑和管纪律，两拨人配合上一节课。","x": "像手术台上的主刀医生加器械护士，一个动刀一个递工具。","c": "教育培训","i": "edu"},{"n": "OMO","a": "线上线下融合","d": "线上招生授课和线下教务服务打通，同一个学员两条线都留记录。","x": "像外卖和堂用同一张会员卡，在哪吃都算积分。","c": "教育培训","i": "edu"},{"n": "教研","a": "教学研究","d": "研究教什么、怎么教、怎么考，产出大纲、讲义和题库。","x": "像餐厅的研发厨房，负责定菜单和配方。","c": "教育培训","i": "edu"},{"n": "助学","a": "班主任服务","d": "给学员配班主任或学习顾问，催进度、答疑、代办报考手续。","x": "像健身私教盯着你练，不然容易半途而废。","c": "教育培训","i": "edu"},{"n": "主考院校","a": "","d": "自考里负责出题、阅卷、发毕业证的那所学校。","x": "像连锁店的品牌方，门店可以很多，牌子只有一块。","c": "教育培训","i": "edu"},{"n": "考纲","a": "考试大纲","d": "官方规定考试范围和各章分值的文件，复习要按它来。","x": "像考试前老师划的重点范围。","c": "教育培训","i": "edu"},{"n": "通过率","a": "合格率","d": "参加考试的人里及格的比例。","x": "像投篮命中率，投出去多少次进了多少。","c": "教育培训","i": "edu"},{"n": "招生蓄水","a": "蓄水","d": "把还没报名的潜在学员先圈进名单里养着，等开班再转化。","x": "像先把水存在池子里，开闸时才有水放。","c": "教育培训","i": "edu"},{"n": "试听课","a": "","d": "免费或低价让学员先上一节，用来判断要不要报名。","x": "像买鞋之前先试穿。","c": "教育培训","i": "edu"},{"n": "退费周期","a": "退款时效","d": "从学员提出退费到钱真正到账要多久，是口碑风险最大的环节。","x": "像退货之后等退款到账的那几天。","c": "教育培训","i": "edu"},{"n": "教学计划","a": "考试计划","d": "一个专业规定要修哪些课、多少学分、几年修完。","x": "像旅行路线图，先去哪后去哪都写清楚。","c": "教育培训","i": "edu"},{"n": "免考","a": "免试","d": "符合条件（比如已有本科学历）可以不参加某几门课的考试。","x": "像考过驾照的人可以免考交规。","c": "教育培训","i": "edu"},{"n": "加分政策","a": "","d": "符合条件（比如年龄满 25 岁）在录取时能多算几分。","x": "像会员日全场额外打九折。","c": "教育培训","i": "edu"},{"n": "学籍","a": "","d": "你在学校系统里的正式身份记录，注册之后才存在。","x": "像会员卡号，证明你确实是这儿的人。","c": "教育培训","i": "edu"},{"n": "预报名","a": "占位报名","d": "先交定金锁住名额，开班前再补齐余款。","x": "像抢演出票先付定金锁定座位。","c": "教育培训","i": "edu"},{"n": "带班量","a": "","d": "一个班主任同时带多少学员，带太多服务就会掉下来。","x": "像一个服务员同时看几桌。","c": "教育培训","i": "edu"},{"n": "课程包","a": "","d": "把几门课打包一起卖，比单买便宜。","x": "像套餐比单点划算。","c": "教育培训","i": "edu"},{"n": "结业证书","a": "","d": "读完课程发的证明材料，不等于学历文凭。","x": "像参加活动发的纪念章，不是毕业证。","c": "教育培训","i": "edu"},{"n": "学习计划表","a": "周计划","d": "把每科要学的内容排到具体哪一周，用来盯进度。","x": "像健身房的训练计划表。","c": "教育培训","i": "edu"},{"n": "GMV","a": "成交总额","d": "一段时间里卖出去的商品总金额，不扣退款也不扣成本。","x": "像流水账上的营业额，热闹不等于赚钱。","c": "电商运营","i": "ec"},{"n": "客单价","a": "AOV","d": "平均每位顾客一次花多少钱。","x": "像一桌客人的均摊消费。","c": "电商运营","i": "ec"},{"n": "复购率","a": "","d": "一段时间内买过两次以上的顾客占比。","x": "像店里回头客的比例。","c": "电商运营","i": "ec"},{"n": "动销率","a": "","d": "有货的商品里真正卖出去过的比例，用来判断库存压不压。","x": "像衣柜里这个季度真穿过的衣服有几件。","c": "电商运营","i": "ec"},{"n": "坑位费","a": "专场费","d": "在主播或达人直播间占一个商品位置先付的固定费用，佣金另算。","x": "像商场里的摊位租金，卖多卖少都得付。","c": "电商运营","i": "ec"},{"n": "转化漏斗","a": "转化路径","d": "从看到、点击、加购到下单，每个环节剩多少人，用来看哪一环在漏人。","x": "像一层层过筛子，看哪层堵住了。","c": "电商运营","i": "ec"},{"n": "履约时效","a": "","d": "从下单到送达用了多久，是用户体验的硬指标。","x": "像外卖承诺的送达时间，晚一分钟就被投诉。","c": "电商运营","i": "ec"},{"n": "退货率","a": "","d": "卖出去又退回来的比例，服饰类通常最高。","x": "像试穿之后放回架子的比例。","c": "电商运营","i": "ec"},{"n": "白牌","a": "无品牌商品","d": "没有品牌溢价、靠性价比卖货的商品，包装上看不到名气。","x": "像超市自有品牌，便宜但没人认得。","c": "电商运营","i": "ec"},{"n": "私域","a": "私域流量","d": "能自己直接触达的用户池，比如微信群、企微好友，不靠平台分发。","x": "像自己家的鱼塘，不用每次去海里捞。","c": "电商运营","i": "ec"},{"n": "投流","a": "信息流投放","d": "花钱买平台的曝光位，把商品推给可能买的人。","x": "像在人流最旺的路口租一块广告牌。","c": "电商运营","i": "ec"},{"n": "爆款","a": "","d": "单量远超同类、还能带来自然流量的那一款商品。","x": "像店里那道人人必点的招牌菜。","c": "电商运营","i": "ec"},{"n": "起量","a": "起量期","d": "订单从零开始明显往上走的那一段。","x": "像火刚点着的那一下，最难也最关键。","c": "电商运营","i": "ec"},{"n": "投产比","a": "ROI","d": "花一块钱广告费能带回多少销售额。","x": "像下注之后赢回来多少钱。","c": "电商运营","i": "ec"},{"n": "种草","a": "","d": "先让人对产品产生兴趣，再等他自己来搜来买。","x": "像先给邻居尝一口，他觉得好吃才来买。","c": "电商运营","i": "ec"},{"n": "详情页","a": "商品详情","d": "商品页里讲参数、卖点和售后那一版内容。","x": "像商品包装背面的说明。","c": "电商运营","i": "ec"},{"n": "主图","a": "首图","d": "搜索列表里第一眼看到的那张图，直接决定点击率。","x": "像店门口的招牌，好不好看决定进不进门。","c": "电商运营","i": "ec"},{"n": "关键词卡位","a": "","d": "花钱让自己的商品排在某个搜索词的前面。","x": "像在路口抢最好的那个摊位。","c": "电商运营","i": "ec"},{"n": "达人分销","a": "分佣带货","d": "让达人以拿提成的方式帮你卖，不先付坑位费。","x": "像让业务员按提成拿钱，卖不出去不花钱。","c": "电商运营","i": "ec"},{"n": "供应链履约","a": "履约","d": "从下单到发货这段的执行能力，包括备货、打包、物流。","x": "像餐厅从接单到出餐的后厨流程。","c": "电商运营","i": "ec"},{"n": "售后工单","a": "","d": "用户投诉或退换货产生的一条待处理记录。","x": "像医院挂号之后拿到的那张就诊单。","c": "电商运营","i": "ec"},{"n": "店铺权重","a": "","d": "平台给店铺的综合评分，由销量、评价、违规记录等决定，影响能拿到多少曝光。","x": "像学生的综合测评排名，排名高才有好的资源。","c": "电商运营","i": "ec"},{"n": "大促节奏","a": "","d": "一次大促分成预热、爆发、返场几个阶段的时间安排。","x": "像电影先点映、再首映、最后加映。","c": "电商运营","i": "ec"},{"n": "平销期","a": "日常销售","d": "没有大促的平常销售时段。","x": "像非节假日的平常生意。","c": "电商运营","i": "ec"},{"n": "库存周转天数","a": "","d": "一批货平均多少天能卖完。","x": "像冰箱里的菜多久吃完一轮。","c": "电商运营","i": "ec"},{"n": "应收账款","a": "应收","d": "货已经发出、钱还没收到的那些账单。","x": "像借出去还没还的钱，账上有、兜里没有。","c": "金融财税","i": "fin"},{"n": "账期","a": "付款周期","d": "供应商交货后多久能拿到钱，常见的有 30、60、90 天。","x": "像赊账时说好月底一起结。","c": "金融财税","i": "fin"},{"n": "保理","a": "应收账款保理","d": "把还没到期的应收账款打折卖给金融机构，先换出现金。","x": "像把还没到期的欠条低价换成现钱应急。","c": "金融财税","i": "fin"},{"n": "贴现","a": "票据贴现","d": "拿没到期的票据去银行换现金，银行扣掉这段等待时间的利息。","x": "像提前退保，要扣一笔手续费。","c": "金融财税","i": "fin"},{"n": "增值税专用发票","a": "专票","d": "可以用来抵扣进项税的那类发票，一般纳税人之间交易才开。","x": "像能抵现金的券，但只能对公使用。","c": "金融财税","i": "fin"},{"n": "进项抵扣","a": "抵扣","d": "采购时付掉的增值税，可以从该缴的税额里扣回来。","x": "像买料时付的税，卖货时能扣回来一部分。","c": "金融财税","i": "fin"},{"n": "现金流","a": "","d": "账上真正能动的钱进出情况，和账面利润不是一回事。","x": "像钱包里的进出，账面赚了钱也可能一时掏不出现金。","c": "金融财税","i": "fin"},{"n": "坏账准备","a": "","d": "预估一部分应收款收不回来，提前在账上留出缓冲。","x": "像知道有人可能不还钱，先偷偷留一笔备用。","c": "金融财税","i": "fin"},{"n": "授信额度","a": "授信","d": "银行或平台愿意借给你的上限。","x": "像信用卡额度，能刷但得还。","c": "金融财税","i": "fin"},{"n": "毛利率","a": "","d": "收入减掉直接成本之后剩下的比例，不含房租和人工。","x": "像卖菜的差价率，进价一块卖两块。","c": "金融财税","i": "fin"},{"n": "摊销","a": "折旧摊销","d": "一笔大支出按使用年限分摊到每个月，不一次性全算进当期。","x": "像买台机器用五年，账上分五年算成本。","c": "金融财税","i": "fin"},{"n": "转移定价","a": "转让定价","d": "关联公司之间交易时定的价格，常用来把利润放到税率低的地方。","x": "像左右口袋倒钱，看哪个口袋少交费。","c": "金融财税","i": "fin"},{"n": "票据背书","a": "背书","d": "把票据转给别人时在背面签章，责任跟着票据一起走。","x": "像转借条时签个名，出了事要担责。","c": "金融财税","i": "fin"},{"n": "资产负债率","a": "","d": "总负债占总资产的比例，看企业借的钱是不是太多。","x": "像房贷占家庭总资产几成。","c": "金融财税","i": "fin"},{"n": "流动比率","a": "","d": "短期能变现的资产够不够覆盖短期要还的钱。","x": "像钱包里的现金够不够还这个月信用卡。","c": "金融财税","i": "fin"},{"n": "收入确认","a": "","d": "按会计准则判断什么时候可以把一笔钱记成收入。","x": "像外卖真正送到手里，这一单才算完成。","c": "金融财税","i": "fin"},{"n": "递延收入","a": "","d": "钱已经收了但服务还没交付，先挂在账上不算收入。","x": "像办了年卡但还没开始上课。","c": "金融财税","i": "fin"},{"n": "税负率","a": "","d": "实际缴的税占收入的比例。","x": "像一顿饭的钱里税费占多少。","c": "金融财税","i": "fin"},{"n": "审计意见","a": "","d": "会计师事务所对报表是否可信给出的结论。","x": "像体检报告最后医生写的那句结论。","c": "金融财税","i": "fin"},{"n": "关联交易","a": "","d": "和自家关联公司之间的买卖，要单独披露。","x": "像左手和右手做生意，得说清公允不公允。","c": "金融财税","i": "fin"},{"n": "财务共享中心","a": "","d": "把各分公司的记账、报销集中到一个部门统一处理。","x": "像小区集中供暖，不用每家自己烧锅炉。","c": "金融财税","i": "fin"},{"n": "预算超支","a": "","d": "实际花的钱超过了批准的额度。","x": "像手机流量用超了，要另外扣钱。","c": "金融财税","i": "fin"},{"n": "诉讼时效","a": "","d": "权利受法律保护的时间窗口，过了这个期限再起诉，法院可能就不支持了。","x": "像优惠券有有效期，过期作废。","c": "法律合规","i": "law"},{"n": "不可抗力","a": "","d": "无法预见、无法避免、也无法克服的事件，出了事可以据此免责。","x": "像台风天航班取消，不算航司违约。","c": "法律合规","i": "law"},{"n": "表见代理","a": "","d": "明明没授权，但看起来像有授权，对方有理由相信，公司仍要认这笔交易。","x": "像有人穿着工服在店里收钱，顾客自然以为他是店员。","c": "法律合规","i": "law"},{"n": "缔约过失","a": "","d": "合同还没签成，一方在谈的过程中有过错造成对方损失，要赔。","x": "像看房谈好又临时反悔，让对方白跑一趟。","c": "法律合规","i": "law"},{"n": "连带责任","a": "","d": "几个责任人里任何一个人都要对全部债务负责，赔完再内部追偿。","x": "像几个人一起担保，谁有钱谁先还。","c": "法律合规","i": "law"},{"n": "举证责任倒置","a": "","d": "本来谁主张谁举证，特殊情形下反过来，要求对方证明自己没责任。","x": "像医疗纠纷里，由医院自证没过错，而不是病人去证明。","c": "法律合规","i": "law"},{"n": "仲裁条款","a": "","d": "合同里约定有争议去仲裁机构、不去法院的条款，一裁终局。","x": "像约定吵架找长辈评理，不去打官司。","c": "法律合规","i": "law"},{"n": "竞业限制","a": "竞业禁止","d": "离职后一段时间不能去对手公司，公司要按月给补偿。","x": "像分手后约定一段时间不见对方朋友，得给补偿才作数。","c": "法律合规","i": "law"},{"n": "尽职调查","a": "DD","d": "交易前把对方的财务、法律、业务查一遍，看有没有埋着坑。","x": "像买房前查产权和抵押情况。","c": "法律合规","i": "law"},{"n": "合规审查","a": "","d": "业务方案上线前，按法律法规和内部制度过一遍。","x": "像出门前检查证件带没带齐。","c": "法律合规","i": "law"},{"n": "违约金调整","a": "","d": "约定的违约金过高或过低，法院可以按实际损失改。","x": "像押金收得太离谱，可以协商退回来。","c": "法律合规","i": "law"},{"n": "善意取得","a": "","d": "不知情、付了合理价钱、手续齐全，就能合法拿到东西，原主人不能直接要回。","x": "像在正规店买到别人偷来的二手货，你可能不用还。","c": "法律合规","i": "law"},{"n": "合同解除权","a": "解约权","d": "满足约定或法定条件时，一方可以单方面终止合同。","x": "像租房合同写明欠租两月就可以解约。","c": "法律合规","i": "law"},{"n": "保密协议","a": "NDA","d": "约定双方不能把对方的内部信息往外说的文件。","x": "像答应朋友不把他的秘密说出去，还立了字据。","c": "法律合规","i": "law"},{"n": "格式条款","a": "","d": "由一方预先写好、对方只能接受的条款。","x": "像停车场门口的告示：进场即视为同意。","c": "法律合规","i": "law"},{"n": "知识产权归属","a": "","d": "成果的版权、专利权到底归谁，必须在合同里写清楚。","x": "像合伙开店前先说清招牌归谁。","c": "法律合规","i": "law"},{"n": "数据合规","a": "","d": "收集和使用个人信息要合法、只取必需、并且告知同意。","x": "像借别人东西前先说清用来干什么、用多久。","c": "法律合规","i": "law"},{"n": "行政处罚","a": "","d": "政府部门对违法行为作出的罚款、警告、吊证等处理。","x": "像交警开的罚单，不服可以申请复议。","c": "法律合规","i": "law"},{"n": "诉讼保全","a": "","d": "起诉时先申请冻结对方财产，防止他转移。","x": "像打官司前先把对方账户按住。","c": "法律合规","i": "law"},{"n": "调解","a": "","d": "第三方居中协调，双方各让一步达成协议。","x": "像邻里吵架找居委会说和。","c": "法律合规","i": "law"},{"n": "电子签章","a": "","d": "有法律效力的电子印章或电子签名。","x": "像网签合同上按的电子手印。","c": "法律合规","i": "law"},{"n": "反商业贿赂","a": "","d": "禁止用回扣、好处费换取交易。","x": "像比赛明令禁止给裁判塞钱。","c": "法律合规","i": "law"},{"n": "分级诊疗","a": "","d": "小病先去社区医院，大病再转上级医院，避免所有人都挤三甲。","x": "像快递先到驿站，再由驿站送上门。","c": "医疗健康","i": "med"},{"n": "门诊统筹","a": "","d": "看门诊的费用也能由医保按比例报销，不用住院才报。","x": "像小额消费也能用会员折扣。","c": "医疗健康","i": "med"},{"n": "起付线","a": "门槛费","d": "医保开始报销之前，自己要先掏够的金额。","x": "像运费满 99 才包邮。","c": "医疗健康","i": "med"},{"n": "封顶线","a": "最高支付限额","d": "医保一年最多给你报多少，超出部分自己承担。","x": "像保险赔付有上限封顶。","c": "医疗健康","i": "med"},{"n": "DRG 付费","a": "DIP|按病种付费","d": "医保按病种给医院打包付钱，不再按检查、药品逐项结算。","x": "像装修报包干价，超支医院自己扛。","c": "医疗健康","i": "med"},{"n": "集采","a": "带量采购","d": "医保把各医院的需求量凑在一起集中采购，用大订单换低价。","x": "像小区团购，量大自然便宜。","c": "医疗健康","i": "med"},{"n": "适应症","a": "","d": "某种药或疗法被批准用于哪些疾病。","x": "像电器的适用电压，用错型号要出问题。","c": "医疗健康","i": "med"},{"n": "临床路径","a": "","d": "某个病从入院到出院的标准治疗步骤和时间表。","x": "像菜谱的步骤，谁照着做出来的都差不多。","c": "医疗健康","i": "med"},{"n": "循证医学","a": "","d": "治疗方案要拿研究数据说话，不靠个人经验拍板。","x": "像判案要有证据，不能凭感觉。","c": "医疗健康","i": "med"},{"n": "靶向治疗","a": "","d": "针对肿瘤特定基因或蛋白的药物，比化疗更精准、副作用更小。","x": "像快递按门牌号送到户，而不是整条街乱投。","c": "医疗健康","i": "med"},{"n": "处方流转","a": "","d": "电子处方从医院流到药店，患者可以就近取药。","x": "像线上下单后到附近门店取货。","c": "医疗健康","i": "med"},{"n": "随访","a": "","d": "治疗结束后定期回访，看恢复情况和有没有复发。","x": "像买完东西之后的售后回访。","c": "医疗健康","i": "med"},{"n": "三甲医院","a": "","d": "国内医院等级里最高的一档，即三级甲等。","x": "像酒店里的五星级。","c": "医疗健康","i": "med"},{"n": "医保目录","a": "","d": "哪些药和诊疗项目可以用医保报销的那份清单。","x": "像餐厅的优惠券可用清单，不在单上的只能原价。","c": "医疗健康","i": "med"},{"n": "特需门诊","a": "","d": "加钱挂的专家号，服务更快更好，但多数项目报销比例低。","x": "像飞机的商务舱，多花钱换舒适。","c": "医疗健康","i": "med"},{"n": "并发症","a": "","d": "治病过程中或之后出现的其他病症。","x": "像修水管时不小心把墙皮碰掉了。","c": "医疗健康","i": "med"},{"n": "知情同意书","a": "","d": "治疗或手术前，医生说明风险和替代方案、患者签字的文件。","x": "像坐过山车前签的风险告知。","c": "医疗健康","i": "med"},{"n": "多学科会诊","a": "MDT","d": "几个科室的医生一起讨论同一个复杂病例，定统一方案。","x": "像几个老师一起给一道难题会诊。","c": "医疗健康","i": "med"},{"n": "院内感染","a": "","d": "住院期间在医院里新得的感染。","x": "像住酒店期间染上了别的客人的感冒。","c": "医疗健康","i": "med"},{"n": "药占比","a": "","d": "药品收入占医疗总收入的比例，用来控制乱开药。","x": "像一家店靠卖配件赚的钱占总营收多少。","c": "医疗健康","i": "med"},{"n": "床位周转率","a": "","d": "一张床一年能收治多少病人。","x": "像餐厅的翻台率。","c": "医疗健康","i": "med"},{"n": "康复期","a": "","d": "治疗结束到身体功能恢复的那段时间。","x": "像装修完工后还要通风晾一段时间。","c": "医疗健康","i": "med"},{"n": "OEE","a": "设备综合效率","d": "设备实际产出和理论最大产出的比值，用来看设备到底有没有被用满。","x": "像跑一趟的实际平均车速对比最高车速。","c": "制造工业","i": "mfg"},{"n": "节拍时间","a": "Takt","d": "产线必须每隔多久出一件产品，才能刚好满足客户需求。","x": "像快餐店高峰期每 30 秒必须出一份餐。","c": "制造工业","i": "mfg"},{"n": "良率","a": "合格率","d": "投进去的料里做出合格品的比例。","x": "像一锅做十个，成功几个。","c": "制造工业","i": "mfg"},{"n": "首件检验","a": "首检","d": "每批开工先做一件全尺寸检查，确认没问题再批量干。","x": "像打印前先试印一页，看看排版对不对。","c": "制造工业","i": "mfg"},{"n": "防呆","a": "poka-yoke","d": "从设计上让错误装不进去、漏不掉，不指望人不出错。","x": "像 U 盘插反了根本插不进去。","c": "制造工业","i": "mfg"},{"n": "看板管理","a": "Kanban","d": "用卡片或电子屏告诉每道工序该做什么、做多少、什么时候要。","x": "像餐厅传菜口的点单条，后厨照着做。","c": "制造工业","i": "mfg"},{"n": "安灯系统","a": "Andon","d": "工位一出问题就按灯呼叫，管理立刻到场处理。","x": "像飞机座位上的呼叫铃。","c": "制造工业","i": "mfg"},{"n": "工装夹具","a": "夹具","d": "加工时固定和定位零件的专用工具，保证每一件位置都一样。","x": "像切菜用的模具，切出来大小一致。","c": "制造工业","i": "mfg"},{"n": "工艺路线","a": "工艺卡","d": "一件产品从毛坯到成品要经过的工序顺序。","x": "像菜谱的步骤顺序，变了味道就不对。","c": "制造工业","i": "mfg"},{"n": "MES","a": "制造执行系统","d": "车间里的生产管理系统，管工单、报工和质量追溯。","x": "像餐厅的点单系统，前台下单后厨立刻看得见。","c": "制造工业","i": "mfg"},{"n": "5S","a": "","d": "整理、整顿、清扫、清洁、素养，车间现场管理的基本动作。","x": "像厨房收工前的清理规矩。","c": "制造工业","i": "mfg"},{"n": "呆滞料","a": "","d": "长期不用、白占着仓库的物料。","x": "像冰箱里放到过期的食材。","c": "制造工业","i": "mfg"},{"n": "BOM","a": "物料清单","d": "做一件产品需要哪些料、各需要多少。","x": "像菜谱前面的配料表。","c": "制造工业","i": "mfg"},{"n": "来料加工","a": "","d": "客户把料送来，你只负责加工、按件收加工费。","x": "像代客缝衣服，布是客人自己带的。","c": "制造工业","i": "mfg"},{"n": "齐套率","a": "","d": "一个工单需要的料齐了几成，不齐就开不了工。","x": "像做菜缺一样配料就下不了锅。","c": "制造工业","i": "mfg"},{"n": "换型时间","a": "","d": "一条产线从做 A 产品切换到 B 产品要停多久。","x": "像厨房做完一道菜再做下一道，要洗锅换灶。","c": "制造工业","i": "mfg"},{"n": "设备点检","a": "","d": "开机前按清单逐项检查设备状态。","x": "像出车前绕车看一圈。","c": "制造工业","i": "mfg"},{"n": "报废率","a": "","d": "做坏到只能扔掉的产品比例。","x": "像裁布时废掉的那些边角料。","c": "制造工业","i": "mfg"},{"n": "产能利用率","a": "","d": "实际产量占理论最大产能的比例。","x": "像一辆车到底坐满了没有。","c": "制造工业","i": "mfg"},{"n": "委外加工","a": "外协","d": "自己做不完的部分交给外面的厂做。","x": "像餐厅忙不过来，把部分菜交给中央厨房。","c": "制造工业","i": "mfg"},{"n": "工时定额","a": "","d": "做一件产品标准给多少工时，用来算工钱和排产。","x": "像外卖平台给的预计送达时间。","c": "制造工业","i": "mfg"},{"n": "精益生产","a": "","d": "把不增值的动作、等待和库存全部去掉。","x": "像把跑步路线上的绕路全删掉。","c": "制造工业","i": "mfg"},{"n": "三电","a": "","d": "电池、电机、电控，电动车最核心的三块。","x": "像人的心脏、肌肉和神经。","c": "汽车","i": "car"},{"n": "热失控","a": "","d": "电池温度失控后连锁升温，严重时会起火。","x": "像锅里的油温失控，冒烟起火。","c": "汽车","i": "car"},{"n": "增程","a": "增程式","d": "车轮由电机驱动，发动机只负责发电、不直接驱动车轮。","x": "像充电宝给手机供电，手机本身靠电池跑。","c": "汽车","i": "car"},{"n": "双离合","a": "DCT","d": "两套离合器交替工作，换挡快，但低速容易顿挫。","x": "像两个人轮流接力，衔接快，配合不好就卡。","c": "汽车","i": "car"},{"n": "底盘调校","a": "","d": "对悬架、转向、制动的参数做调整，决定开起来是软还是硬。","x": "像把床垫软硬调到合适。","c": "汽车","i": "car"},{"n": "整车 OTA","a": "OTA 升级","d": "通过网络给已经卖出去的车升级软件甚至新功能。","x": "像手机系统远程更新。","c": "汽车","i": "car"},{"n": "轴距","a": "","d": "前后轮中心之间的距离，影响车内空间和行驶稳定性。","x": "像两人抬担子的间距，宽了稳但转不开。","c": "汽车","i": "car"},{"n": "续航达成率","a": "","d": "实际能跑的里程和官方标称里程的比值。","x": "像手机标称待机三天，实际用一天半。","c": "汽车","i": "car"},{"n": "换电","a": "","d": "不充电，直接把没电的电池包换成满电的。","x": "像桶装水送新桶、换空桶。","c": "汽车","i": "car"},{"n": "电池包","a": "","d": "由很多电芯组成、带外壳和散热的一整个电池总成。","x": "像一箱鸡蛋连着托盘和缓冲棉。","c": "汽车","i": "car"},{"n": "电控","a": "","d": "控制电机和电池怎么工作的电子系统。","x": "像人的神经，负责把命令传到该动的地方。","c": "汽车","i": "car"},{"n": "快充协议","a": "","d": "车和充电桩商量怎么充电的规则，决定能充多快。","x": "像两个人先商量用哪种语言说话。","c": "汽车","i": "car"},{"n": "冷启动","a": "","d": "低温环境下车辆或系统的第一次启动。","x": "像冬天早上第一把打火最难。","c": "汽车","i": "car"},{"n": "车机","a": "","d": "车里的中控屏和它跑的那套系统。","x": "像把一台平板电脑装进了车里。","c": "汽车","i": "car"},{"n": "自动辅助驾驶","a": "智驾","d": "帮你保持车道、跟车、变道的功能，但人必须盯着随时接管。","x": "像定速巡航的升级版，司机不能睡。","c": "汽车","i": "car"},{"n": "三包","a": "","d": "包修、包换、包退的售后规定。","x": "像买了不满意能退换的承诺。","c": "汽车","i": "car"},{"n": "保值率","a": "","d": "开了几年之后卖二手能卖回原价的几成。","x": "像手机用两年还能卖多少钱。","c": "汽车","i": "car"},{"n": "容积率","a": "","d": "小区总建筑面积除以用地面积，数值越高住得越挤。","x": "像一间房里塞几个人。","c": "房地产建筑","i": "estate"},{"n": "楼面价","a": "","d": "土地总价除以可建面积，算出每平米房子摊到的地价。","x": "像包场费摊到每个客人头上。","c": "房地产建筑","i": "estate"},{"n": "装配式建筑","a": "","d": "墙板、楼梯在工厂预制好，运到工地像搭积木一样拼起来。","x": "像宜家家具的预制件现场组装。","c": "房地产建筑","i": "estate"},{"n": "预售制","a": "期房","d": "房子还没盖好就先卖，用购房款给工程回款。","x": "像电影预售票，上映前先付钱。","c": "房地产建筑","i": "estate"},{"n": "毛坯房","a": "","d": "只做好结构和基础水电，装修自己搞。","x": "像买半成品菜，回家自己下锅。","c": "房地产建筑","i": "estate"},{"n": "精装房","a": "","d": "开发商统一装修好再交付，拎包入住。","x": "像买成衣，直接就能穿。","c": "房地产建筑","i": "estate"},{"n": "验槽","a": "","d": "基础开挖后检查土质和标高是否符合设计，合格才能浇混凝土。","x": "像铺地板前先看地面平不平。","c": "房地产建筑","i": "estate"},{"n": "工期索赔","a": "","d": "因甲方或不可抗力拖了工期，施工方要求补时间和费用。","x": "像外卖因店家原因延迟，可以要求补偿。","c": "房地产建筑","i": "estate"},{"n": "交付标准","a": "","d": "合同里写明的交房条件，比如门窗品牌、层高、绿化率。","x": "像买车时那张配置单。","c": "房地产建筑","i": "estate"},{"n": "得房率","a": "","d": "套内能实际使用的面积占建筑面积的比例。","x": "像买一箱苹果，去掉箱子和泡沫还剩多少。","c": "房地产建筑","i": "estate"},{"n": "公摊面积","a": "公摊","d": "楼道、电梯、配电间这些公共部分摊到每户头上的面积。","x": "像合租时客厅也算进每个人的房租。","c": "房地产建筑","i": "estate"},{"n": "五证","a": "","d": "卖房必须齐备的五份许可证，缺一不能网签。","x": "像开餐厅要备齐营业执照和卫生许可。","c": "房地产建筑","i": "estate"},{"n": "网签","a": "","d": "在房管系统里正式登记买卖合同，才算走完法律程序。","x": "像领结婚证，办过酒席不等于合法。","c": "房地产建筑","i": "estate"},{"n": "资金监管","a": "","d": "购房款先放进监管账户，过户完成后才划给卖家。","x": "像网购的担保交易，确认收货才放款。","c": "房地产建筑","i": "estate"},{"n": "限购","a": "","d": "规定哪些人、最多能买几套房。","x": "像景区限流，一天只放多少人进。","c": "房地产建筑","i": "estate"},{"n": "交付验房","a": "验房","d": "交房时逐项检查质量，把问题列成清单要求整改。","x": "像提车时先绕车检查一遍再签收。","c": "房地产建筑","i": "estate"},{"n": "物业费起算","a": "","d": "从哪天开始交物业费，通常按交付通知书的日期。","x": "像租房从入住那天开始算房租。","c": "房地产建筑","i": "estate"},{"n": "OKR","a": "目标与关键结果","d": "定一个方向性目标，再配几个可量化的检验点。","x": "像跑步定下配速目标和分段成绩。","c": "人力资源","i": "hr"},{"n": "人才盘点","a": "","d": "定期把团队每个人的能力、业绩、潜力过一遍，决定培养和调整。","x": "像年底盘库，看清哪些货好卖、哪些压着。","c": "人力资源","i": "hr"},{"n": "胜任力模型","a": "","d": "某个岗位要做好需要哪些能力和行为标准。","x": "像招聘启事背后那条真正的合格线。","c": "人力资源","i": "hr"},{"n": "绩效校准","a": "打分校准","d": "各部门打分口径不同，开会横向拉齐，避免都给自家人打高分。","x": "像几个老师一起改卷，先统一评分标准。","c": "人力资源","i": "hr"},{"n": "人才梯队","a": "继任计划","d": "每个关键岗位都提前准备好一到两个接班人。","x": "像球队的替补席，主力伤了有人顶。","c": "人力资源","i": "hr"},{"n": "雇主品牌","a": "","d": "求职者对你的公司是什么印象。","x": "像一家店在街坊里的口碑。","c": "人力资源","i": "hr"},{"n": "人员编制","a": "编制","d": "一个部门允许招多少人，由预算和组织架构定。","x": "像公交车上的座位数，满了就不再上人。","c": "人力资源","i": "hr"},{"n": "人力成本率","a": "","d": "人力总支出占营收的比例。","x": "像一家店的工资占营业额几成。","c": "人力资源","i": "hr"},{"n": "离职面谈","a": "","d": "员工提出离职时的一次谈话，了解真实原因。","x": "像退房时问一句住得哪里不舒服。","c": "人力资源","i": "hr"},{"n": "岗位说明书","a": "JD","d": "写清这个岗位做什么、要求什么、向谁汇报。","x": "像家电说明书，写清用途和注意事项。","c": "人力资源","i": "hr"},{"n": "薪酬带宽","a": "","d": "一个职级允许的工资区间，新人和老手在区间里浮动。","x": "像同房型的房价，淡旺季不一样但有个上下限。","c": "人力资源","i": "hr"},{"n": "试用期工资","a": "","d": "试用期间的工资，法定不得低于转正后的八成。","x": "像试营业期打八折。","c": "人力资源","i": "hr"},{"n": "年终奖计提","a": "","d": "按业绩预先算出要发的年终奖并计入当期成本。","x": "像提前把过年的红包钱存起来。","c": "人力资源","i": "hr"},{"n": "培训生计划","a": "管培生","d": "招应届生集中培养一段时间，再定岗。","x": "像学徒工先跟着师傅学，学成了再独立上手。","c": "人力资源","i": "hr"},{"n": "弹性工作制","a": "","d": "在保证总工时的前提下可以自己安排上下班时间。","x": "像自助餐，几点去吃自己定。","c": "人力资源","i": "hr"},{"n": "员工满意度调研","a": "","d": "用匿名问卷了解大家对公司的真实感受。","x": "像餐厅门口的意见卡。","c": "人力资源","i": "hr"},{"n": "对齐","a": "","d": "几个人把各自的理解和口径统一，避免各做各的。","x": "像几个人对表，先把时间调成一样的。","c": "互联网职场黑话","i": "jargon"},{"n": "拉通","a": "串一下","d": "把分散在各团队的信息和流程串起来，让大家知道的是同一件事。","x": "像把几节车厢连成一列火车。","c": "互联网职场黑话","i": "jargon"},{"n": "抓手","a": "着力点","d": "能立刻用上力、还能带动全局的那个切入点。","x": "像提箱子时握住的那个把手。","c": "互联网职场黑话","i": "jargon"},{"n": "闭环","a": "形成闭环","d": "一件事从开始到有结果、有反馈、有人负责，走完一整圈。","x": "像寄快递要有签收，不能只发出去就算完。","c": "互联网职场黑话","i": "jargon"},{"n": "赋能","a": "","d": "给别人提供能力或资源，让他自己能把事做成。","x": "像教人钓鱼，而不是直接送鱼。","c": "互联网职场黑话","i": "jargon"},{"n": "颗粒度","a": "颗粒感","d": "一件事拆得多细，或者数据统计到多细的层级。","x": "像切菜，切丝还是切块，粗细不一样。","c": "互联网职场黑话","i": "jargon"},{"n": "复盘","a": "","d": "事情做完后回看过程，找出哪里做对、哪里做错。","x": "像球队赛后一起看录像回放。","c": "互联网职场黑话","i": "jargon"},{"n": "打法","a": "套路","d": "做成一件事的整体策略和出招顺序。","x": "像打牌时的出牌思路。","c": "互联网职场黑话","i": "jargon"},{"n": "组合拳","a": "","d": "几个动作一起上、互相配合来达成目标。","x": "像拳击里的连击，单出一拳不倒人。","c": "互联网职场黑话","i": "jargon"},{"n": "心智","a": "用户心智","d": "用户一想到某个需求时，第一个蹦出来的是谁。","x": "像一说可乐就想到某个牌子。","c": "互联网职场黑话","i": "jargon"},{"n": "破圈","a": "","d": "从原来的小圈子里扩散到更大的受众。","x": "像小店的招牌菜被外地人专程来吃。","c": "互联网职场黑话","i": "jargon"},{"n": "势能","a": "","d": "攒起来的势头和影响力，能让后面的事更省力。","x": "像下坡时的惯性，越滚越快。","c": "互联网职场黑话","i": "jargon"},{"n": "沉淀","a": "","d": "把经验、内容、数据留下来，下次能直接复用。","x": "像把汤慢慢熬出味道，不是喝完就倒掉。","c": "互联网职场黑话","i": "jargon"},{"n": "落地","a": "落下去","d": "从想法变成真正能执行、能上线的东西。","x": "像图纸变成一栋真房子。","c": "互联网职场黑话","i": "jargon"},{"n": "卡点","a": "","d": "挡住进度的那一个具体问题。","x": "像高速上堵住整条路的那辆车。","c": "互联网职场黑话","i": "jargon"},{"n": "排期","a": "","d": "把要做的事按时间和人力排进日历。","x": "像餐厅的订位表，几点几桌都排好。","c": "互联网职场黑话","i": "jargon"},{"n": "需求评审","a": "过需求","d": "开发之前把需求讲清楚、挑毛病、定范围的会。","x": "像装修前和设计师把方案过一遍。","c": "互联网职场黑话","i": "jargon"},{"n": "迭代","a": "","d": "一小步一小步地改，每一轮都留下能用的版本。","x": "像手机系统的小版本更新。","c": "互联网职场黑话","i": "jargon"},{"n": "冷启动","a": "","d": "一个新产品一个用户都没有时，怎么把第一波人拉进来。","x": "像新店开业第一天，门口一个人都没有。","c": "互联网职场黑话","i": "jargon"},{"n": "用户画像","a": "","d": "把目标用户的特点整理成一张标签清单，用来判断内容做给谁看。","x": "像相亲前列一张对方的条件清单。","c": "互联网职场黑话","i": "jargon"},{"n": "留存","a": "留存率","d": "用过的人过一段时间还会不会回来。","x": "像店的回头客比例。","c": "互联网职场黑话","i": "jargon"},{"n": "拉新","a": "","d": "想办法带来从没来过的新用户。","x": "像发传单把人拉进店。","c": "互联网职场黑话","i": "jargon"},{"n": "促活","a": "","d": "让已经沉默的老用户重新用起来。","x": "像给老会员发张券叫他回来。","c": "互联网职场黑话","i": "jargon"},{"n": "转化","a": "转化率","d": "从看到到完成目标动作（注册、下单）的比例。","x": "像进店的人里最后有多少买了东西。","c": "互联网职场黑话","i": "jargon"},{"n": "北极星指标","a": "","d": "全公司只盯的那一个核心数字。","x": "像开车时只看的那块速度表。","c": "互联网职场黑话","i": "jargon"},{"n": "需求池","a": "","d": "把所有待做的需求收在一起，按优先级排序的清单。","x": "像待办事项清单，先挑急的做。","c": "互联网职场黑话","i": "jargon"},{"n": "干系人","a": "相关方","d": "会被这件事影响、需要通知和商量的人。","x": "像装修时要打招呼的邻居和物业。","c": "互联网职场黑话","i": "jargon"},{"n": "里程碑","a": "","d": "项目里几个关键时间点。","x": "像长跑路上的公里牌。","c": "互联网职场黑话","i": "jargon"},{"n": "搭子","a": "","d": "临时找的、只在某件事上配合的伙伴。","x": "像约着一起打球的人，打完各回各家。","c": "互联网职场黑话","i": "jargon"},{"n": "向上管理","a": "","d": "主动让上级了解进度和难处，争取资源和支持。","x": "像给客户定期汇报，别等出事才说话。","c": "互联网职场黑话","i": "jargon"},{"n": "甩锅","a": "","d": "把出问题的责任推给别人。","x": "像几个人合伙干活，出错了都说不是自己那一步。","c": "互联网职场黑话","i": "jargon"},{"n": "背锅","a": "","d": "不是主要责任，却被算成责任人。","x": "像球队输了球，守门员一个人挨骂。","c": "互联网职场黑话","i": "jargon"},{"n": "曝光量","a": "展现量","d": "广告被看到多少次，不等于被记住。","x": "像传单印了多少张、发出多少张。","c": "市场营销","i": "mkt"},{"n": "点击率","a": "CTR","d": "看到的人里有多少点进去了。","x": "像发一百张传单，有几个人真的进店。","c": "市场营销","i": "mkt"},{"n": "千人成本","a": "CPM","d": "让一千个人看到这条广告要花多少钱。","x": "像按人头算的摊位费。","c": "市场营销","i": "mkt"},{"n": "投放素材","a": "素材","d": "广告用的图、视频和文案。","x": "像门店的橱窗怎么布置。","c": "市场营销","i": "mkt"},{"n": "落地页","a": "","d": "点了广告之后进的那个页面。","x": "像进了店门之后的第一个柜台。","c": "市场营销","i": "mkt"},{"n": "品牌资产","a": "","d": "品牌积累下来的认知、信任和联想。","x": "像老字号那块招牌本身值多少钱。","c": "市场营销","i": "mkt"},{"n": "定位","a": "市场定位","d": "你想在用户心里占住的那个位置。","x": "像货架上你占的那一格，旁边是谁很重要。","c": "市场营销","i": "mkt"},{"n": "卖点","a": "","d": "用户能听懂、又真正在意的那个好处。","x": "像菜单上最想让人点的那句话。","c": "市场营销","i": "mkt"},{"n": "传播矩阵","a": "","d": "在多个渠道同时铺内容，互相带流量。","x": "像同一个品牌在几个商圈同时开店。","c": "市场营销","i": "mkt"},{"n": "内容日历","a": "","d": "提前排好哪天发什么内容。","x": "像电视台的节目单。","c": "市场营销","i": "mkt"},{"n": "裂变","a": "","d": "让老用户带新用户，一环带一环地扩散。","x": "像一个人拉三个人进群。","c": "市场营销","i": "mkt"},{"n": "口碑","a": "","d": "用户主动说出去的好坏评价。","x": "像街坊邻居嘴里对你的评价。","c": "市场营销","i": "mkt"},{"n": "事件营销","a": "","d": "借一个大话题或活动来做传播。","x": "像借节日办一场活动把人吸引过来。","c": "市场营销","i": "mkt"},{"n": "竞品分析","a": "","d": "把对手的产品、价格、打法摸清楚。","x": "像开店前先去对面店里吃一顿。","c": "市场营销","i": "mkt"},{"n": "用户调研","a": "","d": "直接问用户想要什么、卡在哪一步。","x": "像上新菜之前先请老顾客试吃。","c": "市场营销","i": "mkt"},{"n": "品效合一","a": "","d": "既要品牌声量，也要当场带来转化。","x": "像既打广告又当场卖货。","c": "市场营销","i": "mkt"},{"n": "触达","a": "","d": "把信息真正送到用户眼前或手机上。","x": "像敲门把东西送到人手上。","c": "市场营销","i": "mkt"},{"n": "转化成本","a": "获客成本","d": "带来一个下单用户平均要花多少钱。","x": "像拉一个客人进店要花多少传单钱。","c": "市场营销","i": "mkt"},{"n": "AB 测试","a": "A/B 测试","d": "两个版本各给一部分人看，比哪个效果更好。","x": "像两种包装先各卖一周试试。","c": "市场营销","i": "mkt"},{"n": "投放回收期","a": "","d": "广告花出去的钱，多久能靠后续订单赚回来。","x": "像装修投的钱，几个月靠营业额赚回来。","c": "市场营销","i": "mkt"},{"n": "头程","a": "","d": "货物从工厂到目的国或保税仓那一段运输。","x": "像快递的第一段长途。","c": "物流供应链","i": "logi"},{"n": "尾程","a": "最后一公里","d": "送到用户手上的最后一段。","x": "像接力赛的最后一棒。","c": "物流供应链","i": "logi"},{"n": "清关","a": "报关","d": "货物进出境时向海关申报、缴税、被放行的过程。","x": "像过安检加登记，手续不全就过不去。","c": "物流供应链","i": "logi"},{"n": "保税仓","a": "","d": "货物先进保税区仓库，卖出去时才交税出库。","x": "像先把货放在门口的储物柜，卖了再取。","c": "物流供应链","i": "logi"},{"n": "在途库存","a": "","d": "已经在路上、还没到仓的货。","x": "像点了外卖，还在骑手车上。","c": "物流供应链","i": "logi"},{"n": "安全库存","a": "","d": "为应对波动额外留的底货。","x": "像家里常备一袋米，吃完再买就晚了。","c": "物流供应链","i": "logi"},{"n": "断货率","a": "缺货率","d": "顾客想买却买不到的比例。","x": "像想点的那道菜卖完了。","c": "物流供应链","i": "logi"},{"n": "越库","a": "越库作业","d": "货到仓不存放，直接分拨发走。","x": "像公交换乘，不进候车厅直接换下一趟。","c": "物流供应链","i": "logi"},{"n": "分拨中心","a": "","d": "把发往各地的包裹按目的地分开的中转场。","x": "像邮局的分拣台。","c": "物流供应链","i": "logi"},{"n": "干线运输","a": "","d": "城市之间的大批量运输。","x": "像城市间跑的高速大巴。","c": "物流供应链","i": "logi"},{"n": "共同配送","a": "拼车配送","d": "几家货主的货拼一辆车送。","x": "像几个人拼车走同一段路。","c": "物流供应链","i": "logi"},{"n": "逆向物流","a": "","d": "退货、回收、返修这类往回走的物流。","x": "像退快递，货从用户手里往回走。","c": "物流供应链","i": "logi"},{"n": "库位","a": "","d": "仓库里给每种货固定的存放位置编号。","x": "像图书馆每本书的架位号。","c": "物流供应链","i": "logi"},{"n": "拣货路径","a": "","d": "仓库里拿货走的路线，路线越短越快。","x": "像在超市按清单从入口走到收银台。","c": "物流供应链","i": "logi"},{"n": "装载率","a": "","d": "一辆车装了多少比例的空间或重量。","x": "像行李箱塞满没塞满。","c": "物流供应链","i": "logi"},{"n": "时效承诺","a": "","d": "对外承诺几天送到，超时要赔。","x": "像外卖的准时宝。","c": "物流供应链","i": "logi"},{"n": "冷链","a": "","d": "全程控温的运输，生鲜和药品要用。","x": "像出门给菜盖上冰袋。","c": "物流供应链","i": "logi"},{"n": "签收率","a": "","d": "发出的包裹里成功被签收的比例。","x": "像寄出去的信有多少封真的送到了。","c": "物流供应链","i": "logi"},{"n": "翻台率","a": "","d": "一张桌子一天能接待几拨客人。","x": "像停车位一天能停几辆车。","c": "餐饮零售","i": "retail"},{"n": "坪效","a": "","d": "每平米店面一天或一个月能做多少营业额。","x": "像算一平米能挣多少钱。","c": "餐饮零售","i": "retail"},{"n": "出品率","a": "","d": "进货的原料能做出多少可卖的成品。","x": "像一斤肉剔完还能出多少净肉。","c": "餐饮零售","i": "retail"},{"n": "损耗率","a": "","d": "变质、破损、偷拿造成的损失比例。","x": "像水果摊每天要扔掉的烂果。","c": "餐饮零售","i": "retail"},{"n": "备餐","a": "","d": "高峰到来之前，先把常用料和半成品准备好。","x": "像